let db=fs.existsSync(DB)?JSON.parse(fs.readFileSync(DB)):seed();const save=()=>fs.writeFileSync(DB,JSON.stringify(db,null,1));delete db.videos;if(!db.daycare.schoolTime){db.daycare.schoolTime='8:45 AM to 3:30 PM';db.daycare.daycareTime='8:30 AM to 6:30 PM';}if(!db.gallery)db.gallery=[];if(!db.slides)db.slides=[['1','Teacher reading with children around the classroom table'],['2','Story time in the classroom'],['3','Activity corner with learning toys'],['4','Children playing on rockers and slide in the play area'],['5','Kids enjoying the indoor play area'],['6','Colourful indoor play zone with slide and rockers']].map(([n,c])=>({id:'s'+n,src:'/static/slideshow/slide-'+n+'.jpg',photo:'',caption:c}));if(!db.daycare.officeTime)db.daycare.officeTime='Monday to Saturday, 9:00 AM to 4:00 PM';if(!db.holidays)db.holidays=[];{const fake=x=>/\[PLACEHOLDER\]|Sample only|Example announcement|Photo coming soon|\(placeholder\)/i.test(JSON.stringify(x));db.announcements=(db.announcements||[]).filter(a=>!fake(a));db.holidays=db.holidays.filter(h=>!fake(h));db.uniforms=(db.uniforms||[]).filter(u=>!(fake(u)&&!u.photo&&!u.photoUrl));db.kids=(db.kids||[]).filter(k=>!/^Demo Child/.test(k.name||''));}delete db.notes;if(!db.attendance)db.attendance={};delete db.events;delete db.leaves;delete db.log;if(!db.staffNotes)db.staffNotes=[];if(!db.lost)db.lost=[];delete db.receipts;delete db.fees;if(!db.about||/PLACEHOLDER/.test(db.about.body||'')){db.about={title:'About us',body:"Aarunya Kids Preschool is a small, caring preschool in Nizampet, Hyderabad. Our motto is First Light of Learning: we help little ones take their first happy steps into learning in a warm and safe place.\n\nWith a decade of experience in caring for young children, the school is run with deep patience and attention. Our trained didis and staff know how to handle little ones kindly — settling them when they are new, guiding play, and making each day feel calm and friendly.\n\nOur school is managed by a dedicated team of staff trained in the field of education. Each teacher understands how young children grow, learn and feel, and brings that knowledge into the classroom every day. From planning age-appropriate activities to gently noticing each child's needs, our team works together so that every little one feels confident, cared for and ready to learn.\n\nLearning here is playful and hands-on. Children explore with songs, stories, games, art and lots of props and equipment, so they have fun and also learn by doing. We use simple preschool methods that suit this age: learning through play, movement, sensory activities and guided group time, so little minds grow without pressure.\n\nWe also share our culture with care. Children take part in festivals and celebrations such as Guru Purnima and other festivals, so they grow up with warmth, respect and a sense of Sanskriti alongside their everyday play and learning.\n\nParents are always welcome to visit, ask questions and see how their child spends the day. We are a small school with one close group of children, so every family is known and looked after."};}if(db.about&&/hindu/i.test(db.about.body||'')){db.about.body=db.about.body.replace(/\s*\bhindu\b/gi,'');}save();
