const SHORT=12*3600e3,LONG=10*365*24*3600e3,SF=path.join(DATA,'data/sessions.json');
class FileStore extends session.Store{constructor(){super();try{this.m=JSON.parse(fs.readFileSync(SF))}catch{this.m={}}}
 w(){const n=Date.now();for(const k in this.m)if(this.m[k].exp<n)delete this.m[k];fs.writeFile(SF,JSON.stringify(this.m),()=>{})}
 get(id,cb){const r=this.m[id];cb(null,r&&r.exp>Date.now()?r.s:null)}
 set(id,ss,cb){this.m[id]={s:ss,exp:Date.now()+(ss.cookie&&ss.cookie.maxAge?ss.cookie.maxAge:SHORT)};this.w();cb&&cb()}
 destroy(id,cb){delete this.m[id];this.w();cb&&cb()}
 touch(id,ss,cb){this.set(id,ss,cb)}}
const SECRET=process.env.SESSION_SECRET||(()=>{const f=path.join(DATA,'data/.devsecret');try{return fs.readFileSync(f,'utf8')}catch{const v=crypto.randomBytes(32).toString('hex');fs.writeFileSync(f,v);return v}})();
app.use(session({store:new FileStore(),rolling:true,secret:SECRET,resave:false,saveUninitialized:false,cookie:{httpOnly:true,sameSite:'lax',secure:process.env.NODE_ENV==='production'}}));
