const STAYMS=30*24*3600e3,staySig=(id,exp,p)=>crypto.createHmac('sha256',SECRET).update(id+'.'+exp+'.'+p).digest('hex'),stayTok=u=>{const x=Date.now()+STAYMS;return u.id+'.'+x+'.'+staySig(u.id,x,u.pass)};
app.use((q,s,n)=>{if(q.session&&!q.session.uid){const m=/(?:^|;\s*)stay=([^;]+)/.exec(q.headers.cookie||'');if(m){const [id,x,h]=decodeURIComponent(m[1]).split('.'),u=db.users.find(v=>v.id===id);if(u&&+x>Date.now()&&h&&h.length===64&&crypto.timingSafeEqual(Buffer.from(h),Buffer.from(staySig(id,x,u.pass)))){q.session.uid=id;q.session.cookie.maxAge=STAYMS}else s.clearCookie('stay')}}n()});
const me=r=>db.users.find(u=>u.id===r.session.uid);
const need=role=>(q,s,n)=>{const u=me(q);if(!u||(role&&u.role!==role))return s.redirect('/login');q.user=u;n();};
