app.get('/reset/:t',(q,s)=>{const r=findReset(q.params.t),u=r&&db.users.find(u=>u.id===r.uid);if(!u)return s.send(page(q,'Link expired','<h1>This link has expired or was already used</h1><p>Please ask the school for a new link.</p><p>'+phoneLinks()+'</p>'));s.send(page(q,'Set new password',`<h1>Set a new password</h1>${q.query.err?`<div class=warn>${e(q.query.err)}</div>`:''}<div class=card><p>Your username is: <b>${e(u.username)}</b> (please write it down)</p></div><form method=post class=card><label>New password (at least 8 letters/numbers)<input type=password name=n1 minlength=8 required></label><label>Type the new password again<input type=password name=n2 minlength=8 required></label><button class="btn b3">Save new password</button></form>`))});
app.post('/reset/:t',(q,s)=>{const r=findReset(q.params.t),u=r&&db.users.find(u=>u.id===r.uid);if(!u)return s.redirect('/reset/x');const b=q.body,bad=m=>s.redirect('/reset/'+encodeURIComponent(q.params.t)+'?err='+encodeURIComponent(m));if((b.n1||'').length<8)return bad('The new password must be at least 8 characters.');if(b.n1!==b.n2)return bad('The two new passwords do not match.');u.pass=bcrypt.hashSync(b.n1,10);db.resets=db.resets.filter(x=>x!==r);save();s.send(page(q,'Password changed',`<h1>Done!</h1><div class="warn good">Your password has been changed. Your username is <b>${e(u.username)}</b>.</div><p><a class="btn b2 big" href=/login>Go to login</a></p>`));});
app.get('/logout',(q,s)=>(s.clearCookie('stay'),q.session.destroy(()=>s.redirect('/'))));
const warns=k=>{const w=[];if(!k.photo)w.push('Profile picture missing, please update');if(!k.contact)w.push('Missing info: parent contact');if(!k.emName||!k.emPhone)w.push('Missing info: emergency contact');if(!k.allergies)w.push('Missing info: allergies (write "None" if none)');return w;};
const realTxt=v=>{v=(v||'').replace(/\(placeholder\)/i,'').trim();return v&&!/^(none|no|nil|na|n\/a|-)$/i.test(v)?v:''};
const alertBadge=k=>{const a=realTxt(k.allergies),m=realTxt(k.medical);return a||m?`<div class=medalert><span class=mi>!</span><div><b>Medical alert</b>${a?`<p>Allergies: ${e(a)}</p>`:''}${m?`<p>Medical: ${e(m)}</p>`:''}</div></div>`:''};
const pickList=k=>(k.pickup||'').split('\n').map(x=>x.trim()).filter(Boolean);
const summary=u=>{const d=today();return `<div class="card homesum" id=today><h2>Today, ${nice(d)}</h2><div class=sumgrid>${db.kids.filter(k=>k.parentId===u.id).map(k=>{const a=(db.attendance[d]||{})[k.id];return `<div class=sumkid><h3>${e(k.name)}</h3><p><b>Attendance:</b> <span class="fst ${a==='Present'?'p':'a'}">${a||'Not marked yet'}</span></p></div>`}).join('')}</div></div>`};
const lostBox=()=>`<div class="card lostbox"><h2>Lost and found</h2>${db.lost.length?db.lost.map(v=>`<div class=lostitem><b>${e(v.title)}</b>${v.date?` <small>Found on ${nice(v.date)}</small>`:''}${v.note?`<p>${e(v.note)}</p>`:''}</div>`).join(''):'<p>Nothing in lost and found right now.</p>'}<p><small>If something is yours, please ask at the school office.</small></p></div>`;
const PF=[['admNo','Admission no / School ID'],['programme','Class / programme'],['gender','Gender'],['dob','Date of birth','date'],['age','Age in years (0 to 6)','age'],['blood','Blood group'],['aadhaar','Child Aadhaar number'],['father','Father name'],['fatherAadhaar','Father Aadhaar number'],['mother','Mother name'],['motherAadhaar','Mother Aadhaar number'],['address','Home address','ta'],['doctor','Family doctor'],['vacc','Vaccinations (one per line: vaccine - status/date)','ta']];
const age=d=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(d||''))return '';const b=new Date(d),n=new Date();let m=(n.getFullYear()-b.getFullYear())*12+n.getMonth()-b.getMonth();if(n.getDate()<b.getDate())m--;return Math.floor(m/12)+' yrs '+(m%12)+' months';};
const maskA=a=>{a=String(a||'').replace(/\D/g,'');return a?'XXXX XXXX '+a.slice(-4):'';};
const fmtA=a=>String(a||'').replace(/\D/g,'').replace(/(\d{4})(?=\d)/g,'$1 ');
const pfInputs=k=>PF.map(([n,l,t])=>n==='programme'?`<label>${l}<select name=programme>${['Nursery','LKG','UKG','Daycare','Nursery + Daycare','LKG + Daycare','UKG + Daycare'].concat(k.programme&&!/^((Playgroup|Nursery|LKG|UKG)( \+ Daycare)?|Daycare)$/.test(k.programme)?[k.programme]:[]).map(o=>`<option ${k.programme===o?'selected':''}>${e(o)}</option>`).join('')}</select></label>`:t==='ta'?`<label>${l}<textarea name=${n} maxlength=800>${e(k[n])}</textarea></label>`:t==='age'?`<label>${l}<input name=age type=number min=1 max=6 step=1 value="${e(k.age)}"></label>`:`<label>${l}<input name=${n} ${t==='date'?'type=date':''} maxlength=80 value="${e(k[n])}"></label>`).join('');
const profile=(k,admin)=>{const r=(l,v)=>`<tr><th>${l}</th><td>${v||'—'}</td></tr>`;const vac=String(k.vacc||'').split('\n').map(x=>x.trim()).filter(Boolean);return `<div class="card idcard"><div class=idhead><img src=/static/logo.png alt=""><div><b>Aarunya Kids Preschool</b><small>Student ID card</small></div></div><div class=kid>${ph(k.photo)}<div><h2>${e(k.name)}</h2><p><b>ID:</b> ${e(k.admNo)||'—'}</p><p><b>Class:</b> ${e(k.programme)||'—'}</p><p><b>Blood group:</b> <span class=bg>${e(k.blood)||'—'}</span></p></div></div></div>${alertBadge(k)}<div class=card><h2>Full profile</h2><table class=ptab>${r('Full name',e(k.name))}${r('Gender',e(k.gender))}${r('Date of birth',k.dob?nice(k.dob):'')}${r('Age',e(k.age)||age(k.dob))}${r('Class / programme',e(k.programme))}${r('Admission no / School ID',e(k.admNo))}${r('Blood group',e(k.blood))}${r('Child Aadhaar',admin?e(fmtA(k.aadhaar)):e(maskA(k.aadhaar))+(k.aadhaar?' <small>(full number kept by school)</small>':''))}${r('Father',e(k.father))+r('Father Aadhaar',admin?e(fmtA(k.fatherAadhaar)):e(maskA(k.fatherAadhaar)))}${r('Mother',e(k.mother))+r('Mother Aadhaar',admin?e(fmtA(k.motherAadhaar)):e(maskA(k.motherAadhaar)))}${r('Parent phone',e(k.contact))}${r('Home address',e(k.address))}${r('Emergency contact',e(k.emName)+(k.emRel?' ('+e(k.emRel)+')':'')+(k.emPhone?' '+e(k.emPhone):''))}${r('Allergies',e(k.allergies))}${r('Medical notes',e(k.medical))}${r('Family doctor',e(k.doctor))}${r('Photo consent',k.photoConsent?'Yes':'No')}</table></div><div class=card><h2>Vaccinations</h2>${vac.length?`<ul class=vac>${vac.map(v=>`<li>${e(v)}</li>`).join('')}</ul>`:'<p>Not added yet.</p>'}</div><div class=card><h2>Allowed to pick up</h2>${pickList(k).length?`<ul>${pickList(k).map(x=>`<li>${e(x)}</li>`).join('')}</ul>`:'<p>No one added yet.</p>'}</div>`};
const kidCard=(k,admin)=>`<div class=card>${alertBadge(k)}${k.photoConsent?'':'<div class=noconsent><b>No photo consent.</b> Do not use this child in gallery or social media photos.</div>'}${warns(k).map(w=>`<div class=warn>${w}</div>`).join('')}<div class=kid>${ph(k.photo)}<div><h3>${e(k.name)}</h3><p><a class="btn b2" href=/kid/${k.id}>Open full profile</a></p><p><b>Parent contact:</b> ${e(k.contact)||'—'}</p><p><b>Allergies:</b> ${e(k.allergies)||'—'}</p><p><b>Emergency contact:</b> ${e(k.emName)||'—'}${k.emRel?' ('+e(k.emRel)+')':''} ${k.emPhone?`<a class="btn tel" href="tel:${e(k.emPhone.replace(/[^0-9+]/g,''))}">${e(k.emPhone)}</a>`:''}</p><p><b>Medical notes:</b> ${e(k.medical)||'—'}</p><p><b>Photo consent:</b> ${k.photoConsent?'Yes':'No'}</p></div></div><div class=pickup><h4>Allowed to pick up</h4>${pickList(k).length?`<ul>${pickList(k).map(x=>`<li>${e(x)}</li>`).join('')}</ul>`:'<p>No one added yet. Only listed people will be allowed to take the child home.</p>'}</div>
<form method=post enctype=multipart/form-data action=${admin?'/admin/kids/'+k.id:'/parent/kids/'+k.id}>${admin?`<label>Name<input name=name value="${e(k.name)}"></label><label>Parent account<select name=parentId>${db.users.filter(u=>u.role==='parent').map(u=>`<option value=${u.id} ${u.id===k.parentId?'selected':''}>${e(u.name)} (${e(u.username)})</option>`).join('')}</select></label>${pfInputs(k)}`:pfInputs(k).replace(/<label>Admission no[^]*?<\/label>/,'')}<label>Parent contact<input name=contact value="${e(k.contact)}"></label><label>Allergies<input name=allergies value="${e(k.allergies)}"></label><label>Medical notes (asthma, medicines, etc. Write "None" if none)<input name=medical maxlength=300 value="${e(k.medical)}"></label><fieldset class=emf><legend>Emergency contact (if parents cannot be reached)</legend><label>Name<input name=emName maxlength=60 value="${e(k.emName)}"></label><label>Relation<input name=emRel maxlength=30 value="${e(k.emRel)}" placeholder="For example: Uncle"></label><label>Phone<input name=emPhone type=tel maxlength=20 value="${e(k.emPhone)}"></label></fieldset><input type=hidden name=consentForm value=1><label class=chk><input type=checkbox name=photoConsent value=yes ${k.photoConsent?'checked':''}> I agree that the school may use photos of this child in the gallery and on social media</label><label>People allowed to pick up (one per line: name, relation, phone)<textarea name=pickup maxlength=600 placeholder="For example: Grandmother, 98xxxxxxxx">${e(k.pickup)}</textarea></label><label>Photo<input type=file name=photo accept=image/*></label><button class="btn b3">Save</button></form>${admin?`<form method=post action=/admin/kids/${k.id}/delete onsubmit="return confirm('Delete?')"><button class="btn del">Delete</button></form>`:''}</div>`;
app.get('/parent',need('parent'),(q,s)=>s.send(page(q,'My Kids',`<h1>${kidHi(q.user)}</h1><p><a class="btn b1 big" href=/lost>Lost and found</a> <a class="btn b1 big" href=/calendar>Holiday calendar</a></p><p><a class="btn b4" href=/password>Change my password</a> <a class="btn b2" href=/help>Parent guide</a> <a class="btn bout" href=/logout>Log out</a></p>${summary(q.user)}<div id=kids></div><h2>My Kids</h2><p>Tap a child to see the full profile.</p><div class=kidtiles>${db.kids.filter(k=>k.parentId===q.user.id).map(k=>`<a class=kidtile href=/kid/${k.id}>${ph(k.photo)}<b>${e(k.name)}</b><small>${e(k.programme||'')}${k.blood?' · Blood '+e(k.blood):''}</small><span class="btn b1">Open profile</span></a>`).join('')}</div>${db.kids.some(k=>k.parentId===q.user.id)?'':'<div class=card><p>No children linked to your login yet. Please call or WhatsApp the school and we will link your child.</p></div>'}`)));
const PROGS=['Nursery','LKG','UKG','Daycare'];
const addKidForm=(back)=>`<form method=post action=/admin/kids class="card kidedit"><input type=hidden name=back value="${back}"><label>Child's name<input name=name required maxlength=80 placeholder="Type the child's name"></label><label>Parent account<select name=parentId required><option value="" disabled selected>Choose the parent's account</option>${db.users.filter(u=>u.role==='parent').map(u=>`<option value=${u.id}>${e(u.name)} (${e(u.username)})</option>`).join('')}</select></label><p><small>Type the name and pick the parent's existing account. The parent fills in the rest from their own account.</small></p><button class="btn b1 big">Add student</button></form>`;
const kidForm=(k,act,btn,back)=>`<form method=post enctype=multipart/form-data action=${act} class="card kidedit"><input type=hidden name=back value="${back}"><input type=hidden name=consentForm value=1><label>Name<input name=name required maxlength=80 value="${e(k.name)}"></label><label>Parent account<select name=parentId>${db.users.filter(u=>u.role==='parent').map(u=>`<option value=${u.id} ${k.parentId===u.id?'selected':''}>${e(u.name)} (${e(u.username)})</option>`).join('')}</select></label>${pfInputs(k)}<label>Parent contact<input name=contact value="${e(k.contact)}"></label><label>Allergies<input name=allergies value="${e(k.allergies)}"></label><label>Medical notes<input name=medical value="${e(k.medical)}"></label><label>Emergency contact name<input name=emName value="${e(k.emName)}"></label><label>Emergency contact relation<input name=emRel value="${e(k.emRel)}"></label><label>Emergency contact phone<input name=emPhone type=tel value="${e(k.emPhone)}"></label><label>People allowed to pick up (one per line)<textarea name=pickup>${e(k.pickup)}</textarea></label><label class=chk><input type=checkbox name=photoConsent value=yes ${k.photoConsent?'checked':''}> Parent agreed to photo use</label><label>Photo${k.photo?' (upload to replace)':''}<input type=file name=photo accept=image/*></label><button class="btn b1">${btn}</button></form>`;
const goBack=(b,d)=>/^\/(students|kid\/[\w-]+)$/.test(b.back||'')?b.back:d;
app.get('/students',need('admin'),(q,s)=>{const P=id=>(db.users.find(x=>x.id===id)||{}).username||'';const cat=k=>PROGS.find(p=>(k.programme||'').startsWith(p))||'UKG';const f=PROGS.includes(q.query.c)?q.query.c:'';const ks=db.kids.filter(k=>!f||cat(k)===f);const tile=k=>`<div class=kidtile>${ph(k.photo)}<b>${e(k.name)}</b><small>${e(k.programme||'')}${k.blood?' · Blood '+e(k.blood):''}${P(k.parentId)?' · Parent '+e(P(k.parentId)):''}</small><a class="btn b1" href=/kid/${k.id}>Open profile</a> <a class="btn b3" href=/kid/${k.id}#edit>Edit</a></div>`;s.send(page(q,'My Students',`<h1>My Students</h1><p>${db.kids.length} students. Tap Edit to change any detail.</p><p class=filt><a class="btn ${f?'b2':'b1'}" href=/students>All</a> ${PROGS.map(p=>`<a class="btn ${f===p?'b1':'b2'}" href="/students?c=${encodeURIComponent(p)}">${p} (${db.kids.filter(k=>cat(k)===p).length})</a>`).join(' ')}</p><details class=card id=add><summary class="btn b1 big">+ Add student</summary>${addKidForm('/students')}</details>${PROGS.map(p=>{const g=ks.filter(k=>cat(k)===p);return g.length?`<h2>${p}</h2><div class=kidtiles>${g.map(tile).join('')}</div>`:''}).join('')}${ks.length?'':'<p>No students here yet.</p>'}`))});
app.get('/kid/:id',(q,s)=>{const u=me(q);if(!u)return s.redirect('/login');const k=db.kids.find(k=>k.id===q.params.id);if(!k||(u.role!=='admin'&&k.parentId!==u.id))return s.sendStatus(404);const admin=u.role==='admin';s.send(page(q,k.name,`<p><a class="btn b2" href=${admin?'/students':'/parent'}>&larr; Back</a> <button class="btn b4" onclick="print()">Print</button></p>${profile(k,admin)}${admin?`<details class=card id=edit><summary class="btn b3">Edit all details</summary>${kidForm(k,'/admin/kids/'+k.id,'Save changes','/kid/'+k.id)}</details><script>if(location.hash==='#edit'){const d=document.getElementById('edit');d.open=true;d.scrollIntoView()}</script><form method=post action=/admin/kids/${k.id}/delete onsubmit="return confirm('Delete this student?')"><input type=hidden name=back value=/students><button class="btn del">Delete student</button></form>`:`<details class=card><summary class="btn b1 big">Fill in / edit my child's details</summary>${kidCard(k,false)}</details>${attFor(k)}<p><small>To change the child's name, please tell the school office.</small></p>`}`));});
app.get('/lost',need('parent'),(q,s)=>s.send(page(q,'Lost and found',`<h1>Lost and found</h1>${lostBox()}`)));
