const setKid=(k,b,f)=>{if(f){if(k.photo)fs.rm(path.join(UP,k.photo),()=>{});k.photo=f.filename;}['contact','allergies','medical','pickup','emName','emRel','emPhone'].forEach(x=>b[x]!==undefined&&(k[x]=b[x]));if(b.consentForm)k.photoConsent=b.photoConsent==='yes';};
app.post('/parent/kids/:id',need('parent'),upload.single('photo'),(q,s)=>{if(q.body.age!==undefined&&String(q.body.age).trim()!==''&&!ageOk(q.body.age))return s.status(400).send('Child age must be a whole number from 1 to 6 years. <a href="javascript:history.back()">Go back</a>');const k=db.kids.find(k=>k.id===q.params.id&&k.parentId===q.user.id);if(!k)return s.sendStatus(403);setKid(k,q.body,q.file);PF.forEach(([x])=>x!=='admNo'&&q.body[x]!==undefined&&(k[x]=q.body[x]));save();s.redirect('/kid/'+k.id);});
