const slideSrc=x=>x.photo?'/photo/'+encodeURIComponent(x.photo):x.src;
const slider=()=>{const L=db.slides||[];return `<section class=slider aria-label="School photos"><figure class="slide on"><img src=/static/uni/building.jpg alt="Aarunya Kids Preschool entrance"><figcaption>Where little stars shine bright</figcaption></figure>${L.map((x,i)=>`<img class="slide" src="${e(slideSrc(x))}" alt="${e(x.caption||'School photo')}" loading=lazy>`).join('')}<button class=prev aria-label="Previous photo">&#8249;</button><button class=next aria-label="Next photo">&#8250;</button><div class=dots><button class=on aria-label="Photo 1"></button>${L.map((x,i)=>`<button aria-label="Photo ${i+2}"></button>`).join('')}</div></section>`};
const HELP={home:'Pick what you want to change. Tap a big button below.',slides:'These are the big photos that slide on the Home page. Add a photo here, change the order with Up / Down, or tap Replace to swap one.',about:'Change About text here. This is what visitors read on the About page.',news:'Add news here (for example: holiday notice, event). Pinned news stays at the top.',uniform:'Add a uniform photo here. Each item can have a name, a few words and one photo.',gallery:'Add a photo, a video, or a YouTube link for the Gallery page.',daycare:'Change school, daycare and office timings, phone numbers, email and address here. The map on Find us uses this address.',holidays:'Add school holidays here. They show on the Holiday calendar.',kids:'Add children and their details. Only you and their parent can see this.',attendance:'Tick Present or Absent for each child, then tap Save.',staff:'Private notes for staff. Parents never see these.',lost:'Things found at school. Only logged-in parents can see this list.',bookings:'Daycare enquiries sent from the website.',parents:'Add parent logins, reset passwords, and see Forgot login requests.'};
