let MAILER=null;try{if(process.env.SMTP_HOST||process.env.SMTP_USER){const nm=require('nodemailer');MAILER=nm.createTransport(process.env.SMTP_HOST?{host:process.env.SMTP_HOST,port:+(process.env.SMTP_PORT||587),secure:+(process.env.SMTP_PORT||587)===465,auth:{user:process.env.SMTP_USER,pass:process.env.SMTP_PASS}}:{service:'gmail',auth:{user:process.env.SMTP_USER,pass:process.env.SMTP_PASS}});}}catch(x){MAILER=null}
